INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1164601', 'Battle of Kousséri', 'The battle of Kousséri was a major engagement fought between France and the forces of the warlord Rabih az-Zubayr in the Rabih War. The conflict originated in French plans to occupy the Chari-Baguirmi region in modern-day Chad.', 1900, 4, 22, NULL, NULL, NULL, 'day', '22 April 1900', 50, 'https://en.wikipedia.org/wiki/Battle_of_Kouss%C3%A9ri'),
  ('Q5042244', 'Kamerun campaign', 'The Kamerun campaign took place in the German colony of Kamerun in the African theatre of the First World War when the British, French and Belgians invaded the German colony from August 1914 to March 1916. Most of the campaign took place in Kamerun but skirmishes also broke out in British Nigeria.', 1914, 8, 6, 1916, 3, 10, 'day', '6 August 1914 – 10 March 1916', 55, 'https://en.wikipedia.org/wiki/Kamerun_campaign'),
  ('Q4870415', 'Battle of Banjo', 'During the Battle of Banjo or Battle of Banyo, British forces besieged German forces entrenched on the Banjo mountain from 4 to 6 November 1915 during the Kamerun campaign of the First World War. By 6 November much of the German force had deserted, while the rest surrendered.', 1915, 11, 4, 1915, 11, 6, 'day', '4 November 1915 – 6 November 1915', 34, 'https://en.wikipedia.org/wiki/Battle_of_Banjo'),
  ('Q15275784', 'Second Battle of Edea', 'The Second Battle of Edea was the German counter-attack against French forces stationed in the village of Edea during the Kamerun campaign of the First World War. Allied forces from Duala occupied the town following the First Battle of Edea in October 1914.', 1915, 1, 5, NULL, NULL, NULL, 'day', '5 January 1915', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Edea'),
  ('Q1739099', 'Kenya Airways Flight 507', 'Kenya Airways Flight 507 was a scheduled international passenger service between Abidjan, Ivory Coast, and Nairobi, Kenya, with a stopover in Douala, Cameroon, operated by Kenya Airways. On 5 May 2007, the Boeing 737-800 aircraft serving the flight crashed immediately after takeoff from Douala International Airport in Cameroon, killing all 114 occupants onboard.', 2007, 5, 5, NULL, NULL, NULL, 'day', '5 May 2007', 61, 'https://en.wikipedia.org/wiki/Kenya_Airways_Flight_507'),
  ('Q55390549', 'Anglophone Crisis', 'The Anglophone Crisis (French: Crise anglophone), also known as the Ambazonia War, is an ongoing armed conflict in the English-speaking Northwest and Southwest regions of Cameroon, between the Cameroonian government and Ambazonian separatist groups, part of the long-standing Anglophone problem. Following the suppression of 2016–17 protests by Cameroonian authorities, separatists in the Anglophone regions (formerly collectively known as the Southern Cameroons) launched a guerrilla campaign and later proclaimed independence.', 2017, 9, 9, NULL, NULL, NULL, 'day', '9 September 2017', 56, 'https://en.wikipedia.org/wiki/Anglophone_Crisis'),
  ('Q60524385', 'Battle of Batibo', 'The Battle of Batibo occurred on 3 March 2018, when Ambazonian separatists attacked Cameroonian troops on the Bamenda-Batibo Highway, Batibo Subdivision. At the time, it was reportedly the deadliest clash between Cameroonian and Ambazonian forces to date.', 2018, 3, 3, NULL, NULL, NULL, 'day', '3 March 2018', 37, 'https://en.wikipedia.org/wiki/Battle_of_Batibo'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q85503435', 'Ntumbo attack', 'The Ngarbuh massacre took place in northwestern Cameroon on 14 February 2020 during the Anglophone Crisis, and resulted in the murder of 21 civilians, including 13 children, by Cameroonian soldiers and armed Fulani militia.', 2020, 2, 14, NULL, NULL, NULL, 'day', '14 February 2020', 34, 'https://en.wikipedia.org/wiki/Ngarbuh_massacre'),
  ('Q100891384', 'Kumba school massacre', 'The Kumba school massacre took place at Mother Francisca International Bilingual Academy during the Anglophone Crisis, in Kumba, Cameroon, in October 2020.', 2020, 10, 24, NULL, NULL, NULL, 'day', '24 October 2020', 37, 'https://en.wikipedia.org/wiki/Kumba_school_massacre'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods');
